import React from "react";
import { useCurrentFrame, useVideoConfig, AbsoluteFill, interpolate, spring, Easing } from '../remotionShim';
// Google Fonts Loader
const useFontLoader = (fonts: string[]) => {
  const stableFonts = React.useMemo(() => {
    const unique = [...new Set(fonts.map(f => f.trim()))].sort();
    return unique;
  }, [fonts.join("|")]);

  React.useEffect(() => {
    const unloaded = stableFonts.filter(
      (font) =>
        !document.querySelector(
          `link[href*="${font.replace(/\s+/g, "+")}"]`
        )
    );

    if (unloaded.length === 0) return;

    const url = `https://fonts.googleapis.com/css2?${unloaded
      .map((font) => `family=${font.replace(/\s+/g, "+")}:wght@400;500;700`)
      .join("&")}&display=swap`;

    const link = document.createElement("link");
    link.rel = "stylesheet";
    link.href = url;

    document.head.appendChild(link);
  }, [stableFonts]);
};



export type PremiumBadgeProps = Record<string, any>;

const PremiumBadge: React.FC<PremiumBadgeProps> = ({
  backgroundColor = "#000000",
  transparentBackground = true,
  durationInSeconds = 5,
  nameText = "ALEX HORMOZI",
  statText = "$100M+ REVENUE",
  badgeColor = "#0a0a0acc", // Dark translucent
  accentColor = "#CCBA78", // Gold
  textColor = "#FFFFFF",
  alignment = "left",
  scale = 1,
  offsetY = 0,
  uppercase = true,
}) => {
  
  // Load Fonts
  useFontLoader(["Montserrat"]);

  const frame = useCurrentFrame();
  const { fps, width, height } = useVideoConfig();
  const durationInFrames = durationInSeconds * fps;

  // Background Logic
  const bgColor = transparentBackground ? "transparent" : backgroundColor;

  // Animation Config
  const enterDuration = 25; // frames
  const exitDuration = 20; // frames
  const exitStart = durationInFrames - exitDuration;

  // Entrance Spring
  const entranceSpring = spring({
    frame,
    fps,
    config: {
      damping: 12,
      stiffness: 100,
      mass: 0.8,
    },
  });

  // Exit Animation
  const exitInterpolation = interpolate(
    frame,
    [exitStart, durationInFrames],
    [1, 0],
    {
      extrapolateLeft: "clamp",
      extrapolateRight: "clamp",
      easing: Easing.out(Easing.ease),
    }
  );

  // Combine Entrance and Exit
  // During entrance (frame < exitStart), use spring. After, multiply by exit fade.
  // Ideally, use entrance value * exit value to handle opacity/scale correctly.
  
  // Opacity: Spring in 0->1, then fade out 1->0
  const opacity = interpolate(entranceSpring, [0, 1], [0, 1]) * exitInterpolation;
  
  // Y Movement: Slide UP in, Slide DOWN out
  // In: 50 -> 0
  const yIn = interpolate(entranceSpring, [0, 1], [50, 0]);
  // Out: 0 -> 50
  const yOut = interpolate(frame, [exitStart, durationInFrames], [0, 50], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
    easing: Easing.in(Easing.ease),
  });
  
  const translateY = yIn + yOut;

  // Dynamic Styles
  const isCenter = alignment === "center";
  
  const containerStyle: React.CSSProperties = {
    position: "absolute",
    bottom: height * 0.15 + offsetY, // Lower third position
    left: isCenter ? "50%" : width * 0.1,
    transform: `translateX(${isCenter ? "-50%" : "0%"}) translateY(${translateY}px) scale(${scale})`,
    opacity,
    display: "flex",
    flexDirection: "column",
    alignItems: isCenter ? "center" : "flex-start",
    fontFamily: "Montserrat, sans-serif",
  };

  const badgeStyle: React.CSSProperties = {
    backgroundColor: badgeColor,
    border: `1px solid ${accentColor}40`, // 25% opacity border for subtlety
    borderRadius: 60, // Pill shape
    padding: "24px 48px",
    display: "flex",
    flexDirection: "column",
    gap: 4,
    backdropFilter: "blur(12px)",
    boxShadow: "0 8px 32px rgba(0,0,0,0.2)",
    minWidth: 300,
    alignItems: isCenter ? "center" : "flex-start",
  };

  const nameStyle: React.CSSProperties = {
    color: textColor,
    fontSize: 42,
    fontWeight: 700,
    lineHeight: 1,
    letterSpacing: -0.5,
    textTransform: uppercase ? "uppercase" : "none",
    margin: 0,
    whiteSpace: "nowrap",
  };

  const statStyle: React.CSSProperties = {
    color: accentColor,
    fontSize: 24,
    fontWeight: 500,
    lineHeight: 1.2,
    letterSpacing: 1, // Add spacing for premium feel
    textTransform: uppercase ? "uppercase" : "none",
    margin: 0,
    whiteSpace: "nowrap",
  };

  return (
    <AbsoluteFill style={{ backgroundColor: bgColor }}>
      <div style={containerStyle}>
        <div style={badgeStyle}>
          <h1 style={nameStyle}>{nameText}</h1>
          <h2 style={statStyle}>{statText}</h2>
        </div>
      </div>
    </AbsoluteFill>
  );
};

export default PremiumBadge;